// src/components/FlowsheetCanvas.tsx
"use client";
import 'reactflow/dist/style.css';

import React from "react";
import ReactFlow, {
  Background,
  Controls,
  MiniMap,
  Connection,
  Edge,
  OnConnect,
  OnEdgesChange,
  OnNodesChange,
} from "reactflow";

import type { FlowsheetNode } from "@/types/units";
import { ProcessNode } from "@/components/ProcessNode";

// 🔹 اینجا nodeTypes را تعریف می‌کنیم
const nodeTypes = {
  processNode: ProcessNode,
};

interface FlowsheetCanvasProps {
  nodes: FlowsheetNode[];
  edges: Edge[];
  onNodesChange: OnNodesChange;
  onEdgesChange: OnEdgesChange;
  onConnect: OnConnect;
  onDrop: (event: React.DragEvent) => void;
  onDragOver: (event: React.DragEvent) => void;
  onNodeClick: (node: FlowsheetNode) => void;
}

export function FlowsheetCanvas({
  nodes,
  edges,
  onNodesChange,
  onEdgesChange,
  onConnect,
  onDrop,
  onDragOver,
  onNodeClick,
}: FlowsheetCanvasProps) {
  return (
    <div className="w-full h-full">
      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        onDrop={onDrop}
        onDragOver={onDragOver}
        onNodeClick={(_, node) => onNodeClick(node as FlowsheetNode)}
        nodeTypes={nodeTypes}   // 🔹 اینجا از nodeTypes تعریف‌شده استفاده می‌کنیم
        fitView
      >
        <Background gap={16} size={1} />
        <MiniMap pannable zoomable nodeStrokeWidth={1} />
        <Controls />
      </ReactFlow>
    </div>
  );
}
